/**
 * The row read-toggle glyph — the row's only control now that dismiss is gone.
 *
 * A tick rather than a circle: with unread status already carried by the pip on
 * the category icon, this button does not need to restate the state. It states
 * the action, and "mark as read" is a tick in every mail client there has ever
 * been. Direction is carried by colour (muted = will mark read, brand = already
 * read, click to undo) plus the label.
 */
export function CheckIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true" {...props}>
      <path
        d="M3.5 9.5L7 13L14.5 5"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

